  "recovered_c": "uint64_t fn_15(uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  size_t need = 0;\n  size_t o = 0;\n  for (size_t i = 0; i < len; i++) {\n    size_t r = 1;\n    while ((i + r < len) && (in[i + r] == in[i]) && (r < 0xff)) {\n      r++;\n    }\n    need += 2;\n  }\n  if (out_cap < need) {\n    return 0xffffffffffffffff;\n  }\n  for (size_t i = 0; i < len; i++) {\n    size_t r = 1;\n    while ((i + r < len) && (in[i + r] == in[i]) && (r < 0xff)) {\n      r++;\n    }\n    out[o++] = (uint8_t)r;\n    out[o++] = in[i];\n  }\n  return o;\n}"
